package com.bank.rsocket.metrics;

import io.micrometer.core.instrument.MeterRegistry;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import java.util.concurrent.atomic.AtomicInteger;

// Exposes rsocket_active_connections so the HPA can scale on it.
@Slf4j
@Component
public class ConnectionMetrics {
    private final AtomicInteger active = new AtomicInteger(0);

    public ConnectionMetrics(MeterRegistry registry) {
        registry.gauge("rsocket_active_connections", active);
    }

    public void onConnect() {
        int n = active.incrementAndGet();
        log.info("Client connected. Active connections = {}", n);
    }

    public void onDisconnect() {
        int n = active.decrementAndGet();
        log.info("Client disconnected. Active connections = {}", n);
    }
}
