package com.bank.rsocket.client;

import io.rsocket.core.Resume;
import lombok.extern.slf4j.Slf4j;
import org.springframework.messaging.rsocket.RSocketRequester;
import reactor.util.retry.Retry;
import java.time.Duration;

@Slf4j
public class ScalableClient {
    private final RSocketRequester requester;

    public ScalableClient(RSocketRequester.Builder builder) {
        this.requester = builder
            .rsocketConnector(c -> c
                // keep-alive patient enough to survive a rolling-update handover
                .keepAlive(Duration.ofSeconds(30), Duration.ofSeconds(120))
                // resume so a rescheduled pod does not kill the stream
                .resume(new Resume()
                    .sessionDuration(Duration.ofMinutes(5))
                    .retry(Retry.backoff(10, Duration.ofSeconds(1)))))
            // DNS name resolves via the TCP LB (sticky) — or use client-side LB pool
            .tcp("rsocket-trading", 7000);
        log.info("ScalableClient connected with resume + tuned keep-alive");
    }

    public RSocketRequester requester() { return requester; }
}
